package com.chk.assetlisting.data;

import android.content.ContentValues;
import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.database.sqlite.SQLiteOpenHelper;
import android.text.TextUtils;
import com.chk.assetlisting.model.Asset;
import com.chk.assetlisting.model.Game;
import com.chk.assetlisting.model.Region;
import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;
import java.util.ArrayList;
import java.util.List;

public class DatabaseHelper extends SQLiteOpenHelper {
    private static final String DATABASE_NAME="chk_asset_manager.db";
    private static final int DATABASE_VERSION=1;
    public DatabaseHelper(Context context){super(context,DATABASE_NAME,null,DATABASE_VERSION);}
    @Override public void onConfigure(SQLiteDatabase db){super.onConfigure(db);db.setForeignKeyConstraintsEnabled(true);}
    @Override public void onCreate(SQLiteDatabase db){
        db.execSQL("CREATE TABLE games (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,description TEXT DEFAULT '',cover_uri TEXT DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL)");
        db.execSQL("CREATE TABLE regions (id INTEGER PRIMARY KEY AUTOINCREMENT,game_id INTEGER NOT NULL,name TEXT NOT NULL,type TEXT DEFAULT '',image_uri TEXT DEFAULT '',notes TEXT DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,FOREIGN KEY(game_id) REFERENCES games(id) ON DELETE CASCADE)");
        db.execSQL("CREATE TABLE assets (id INTEGER PRIMARY KEY AUTOINCREMENT,game_id INTEGER NOT NULL,region_id INTEGER DEFAULT 0,name TEXT NOT NULL,category TEXT DEFAULT '',description TEXT DEFAULT '',file_name TEXT DEFAULT '',file_path TEXT DEFAULT '',status INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,FOREIGN KEY(game_id) REFERENCES games(id) ON DELETE CASCADE)");
        db.execSQL("CREATE TABLE asset_images (id INTEGER PRIMARY KEY AUTOINCREMENT,asset_id INTEGER NOT NULL,image_uri TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(asset_id) REFERENCES assets(id) ON DELETE CASCADE)");
        db.execSQL("CREATE INDEX idx_regions_game ON regions(game_id)");db.execSQL("CREATE INDEX idx_assets_game ON assets(game_id)");db.execSQL("CREATE INDEX idx_assets_region ON assets(region_id)");db.execSQL("CREATE INDEX idx_assets_status ON assets(status)");db.execSQL("CREATE INDEX idx_images_asset ON asset_images(asset_id)");
    }
    @Override public void onUpgrade(SQLiteDatabase db,int oldVersion,int newVersion){}

    public long saveGame(Game game){SQLiteDatabase db=getWritableDatabase();long now=System.currentTimeMillis();ContentValues v=new ContentValues();v.put("name",game.getName().trim());v.put("description",safe(game.getDescription()));v.put("cover_uri",safe(game.getCoverUri()));v.put("updated_at",now);if(game.getId()==0){v.put("created_at",now);return db.insertOrThrow("games",null,v);}db.update("games",v,"id=?",new String[]{String.valueOf(game.getId())});return game.getId();}
    public Game getGame(long gameId){try(Cursor c=getReadableDatabase().rawQuery("SELECT g.*,COUNT(a.id) asset_count,SUM(CASE WHEN a.status=2 THEN 1 ELSE 0 END) integrated_count FROM games g LEFT JOIN assets a ON a.game_id=g.id WHERE g.id=? GROUP BY g.id",new String[]{String.valueOf(gameId)})){if(c.moveToFirst())return readGame(c);}return null;}
    public List<Game> getGames(){List<Game> out=new ArrayList<>();String sql="SELECT g.*,COUNT(a.id) asset_count,SUM(CASE WHEN a.status=2 THEN 1 ELSE 0 END) integrated_count FROM games g LEFT JOIN assets a ON a.game_id=g.id GROUP BY g.id ORDER BY g.updated_at DESC,g.name COLLATE NOCASE";try(Cursor c=getReadableDatabase().rawQuery(sql,null)){while(c.moveToNext())out.add(readGame(c));}return out;}
    private Game readGame(Cursor c){Game g=new Game();g.setId(c.getLong(c.getColumnIndexOrThrow("id")));g.setName(c.getString(c.getColumnIndexOrThrow("name")));g.setDescription(c.getString(c.getColumnIndexOrThrow("description")));g.setCoverUri(c.getString(c.getColumnIndexOrThrow("cover_uri")));g.setUpdatedAt(c.getLong(c.getColumnIndexOrThrow("updated_at")));g.setAssetCount(c.getInt(c.getColumnIndexOrThrow("asset_count")));g.setIntegratedCount(c.getInt(c.getColumnIndexOrThrow("integrated_count")));return g;}
    public void deleteGame(long id){getWritableDatabase().delete("games","id=?",new String[]{String.valueOf(id)});}

    public long saveRegion(Region r){SQLiteDatabase db=getWritableDatabase();long now=System.currentTimeMillis();ContentValues v=new ContentValues();v.put("game_id",r.getGameId());v.put("name",r.getName().trim());v.put("type",safe(r.getType()));v.put("image_uri",safe(r.getImageUri()));v.put("notes",safe(r.getNotes()));v.put("updated_at",now);if(r.getId()==0){v.put("created_at",now);touchGame(r.getGameId());return db.insertOrThrow("regions",null,v);}db.update("regions",v,"id=?",new String[]{String.valueOf(r.getId())});touchGame(r.getGameId());return r.getId();}
    public Region getRegion(long id){try(Cursor c=getReadableDatabase().rawQuery("SELECT r.*,COUNT(a.id) asset_count,SUM(CASE WHEN a.status=2 THEN 1 ELSE 0 END) integrated_count FROM regions r LEFT JOIN assets a ON a.region_id=r.id WHERE r.id=? GROUP BY r.id",new String[]{String.valueOf(id)})){if(c.moveToFirst())return readRegion(c);}return null;}
    public List<Region> getRegions(long gameId){List<Region> out=new ArrayList<>();String sql="SELECT r.*,COUNT(a.id) asset_count,SUM(CASE WHEN a.status=2 THEN 1 ELSE 0 END) integrated_count FROM regions r LEFT JOIN assets a ON a.region_id=r.id WHERE r.game_id=? GROUP BY r.id ORDER BY r.name COLLATE NOCASE";try(Cursor c=getReadableDatabase().rawQuery(sql,new String[]{String.valueOf(gameId)})){while(c.moveToNext())out.add(readRegion(c));}return out;}
    private Region readRegion(Cursor c){Region r=new Region();r.setId(c.getLong(c.getColumnIndexOrThrow("id")));r.setGameId(c.getLong(c.getColumnIndexOrThrow("game_id")));r.setName(c.getString(c.getColumnIndexOrThrow("name")));r.setType(c.getString(c.getColumnIndexOrThrow("type")));r.setImageUri(c.getString(c.getColumnIndexOrThrow("image_uri")));r.setNotes(c.getString(c.getColumnIndexOrThrow("notes")));r.setAssetCount(c.getInt(c.getColumnIndexOrThrow("asset_count")));r.setIntegratedCount(c.getInt(c.getColumnIndexOrThrow("integrated_count")));return r;}
    public void deleteRegion(long id){SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("region_id",0);db.update("assets",v,"region_id=?",new String[]{String.valueOf(id)});db.delete("regions","id=?",new String[]{String.valueOf(id)});db.setTransactionSuccessful();}finally{db.endTransaction();}}

    public long saveAsset(Asset a){SQLiteDatabase db=getWritableDatabase();long now=System.currentTimeMillis();ContentValues v=new ContentValues();v.put("game_id",a.getGameId());v.put("region_id",a.getRegionId());v.put("name",a.getName().trim());v.put("category",safe(a.getCategory()));v.put("description",safe(a.getDescription()));v.put("file_name",safe(a.getFileName()));v.put("file_path",safe(a.getFilePath()));v.put("status",a.getStatus());v.put("updated_at",now);db.beginTransaction();try{long id;if(a.getId()==0){v.put("created_at",now);id=db.insertOrThrow("assets",null,v);}else{id=a.getId();db.update("assets",v,"id=?",new String[]{String.valueOf(id)});}replaceImages(db,id,a.getImageUris());touchGame(a.getGameId());db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}
    private void replaceImages(SQLiteDatabase db,long assetId,List<String> uris){db.delete("asset_images","asset_id=?",new String[]{String.valueOf(assetId)});if(uris==null)return;int order=0;for(String uri:uris){if(TextUtils.isEmpty(uri))continue;ContentValues v=new ContentValues();v.put("asset_id",assetId);v.put("image_uri",uri);v.put("sort_order",order++);db.insert("asset_images",null,v);}}
    public Asset getAsset(long id){String sql="SELECT a.*,COALESCE(r.name,'Sans région') region_name FROM assets a LEFT JOIN regions r ON r.id=a.region_id WHERE a.id=?";try(Cursor c=getReadableDatabase().rawQuery(sql,new String[]{String.valueOf(id)})){if(c.moveToFirst()){Asset a=readAsset(c);a.setImageUris(getAssetImages(id));return a;}}return null;}
    public List<Asset> getAssets(long gameId,long regionId,String query,int status){List<Asset> out=new ArrayList<>();List<String> args=new ArrayList<>();StringBuilder where=new StringBuilder(" WHERE a.game_id=?");args.add(String.valueOf(gameId));if(regionId>0){where.append(" AND a.region_id=?");args.add(String.valueOf(regionId));}if(!TextUtils.isEmpty(query)){where.append(" AND (a.name LIKE ? OR a.category LIKE ? OR a.description LIKE ? OR a.file_name LIKE ?)");String p="%"+query.trim()+"%";args.add(p);args.add(p);args.add(p);args.add(p);}if(status>=0){where.append(" AND a.status=?");args.add(String.valueOf(status));}String sql="SELECT a.*,COALESCE(r.name,'Sans région') region_name,(SELECT image_uri FROM asset_images ai WHERE ai.asset_id=a.id ORDER BY sort_order LIMIT 1) main_image FROM assets a LEFT JOIN regions r ON r.id=a.region_id"+where+" ORDER BY a.updated_at DESC,a.name COLLATE NOCASE";try(Cursor c=getReadableDatabase().rawQuery(sql,args.toArray(new String[0]))){while(c.moveToNext()){Asset a=readAsset(c);int i=c.getColumnIndex("main_image");if(i>=0&&!c.isNull(i)){List<String> images=new ArrayList<>();images.add(c.getString(i));a.setImageUris(images);}out.add(a);}}return out;}
    private Asset readAsset(Cursor c){Asset a=new Asset();a.setId(c.getLong(c.getColumnIndexOrThrow("id")));a.setGameId(c.getLong(c.getColumnIndexOrThrow("game_id")));a.setRegionId(c.getLong(c.getColumnIndexOrThrow("region_id")));a.setName(c.getString(c.getColumnIndexOrThrow("name")));a.setCategory(c.getString(c.getColumnIndexOrThrow("category")));a.setDescription(c.getString(c.getColumnIndexOrThrow("description")));a.setFileName(c.getString(c.getColumnIndexOrThrow("file_name")));a.setFilePath(c.getString(c.getColumnIndexOrThrow("file_path")));a.setStatus(c.getInt(c.getColumnIndexOrThrow("status")));a.setUpdatedAt(c.getLong(c.getColumnIndexOrThrow("updated_at")));int i=c.getColumnIndex("region_name");if(i>=0)a.setRegionName(c.getString(i));return a;}
    public List<String> getAssetImages(long id){List<String> out=new ArrayList<>();try(Cursor c=getReadableDatabase().query("asset_images",new String[]{"image_uri"},"asset_id=?",new String[]{String.valueOf(id)},null,null,"sort_order ASC")){while(c.moveToNext())out.add(c.getString(0));}return out;}
    public void updateAssetStatus(long id,int status){Asset a=getAsset(id);if(a==null)return;ContentValues v=new ContentValues();v.put("status",status);v.put("updated_at",System.currentTimeMillis());getWritableDatabase().update("assets",v,"id=?",new String[]{String.valueOf(id)});touchGame(a.getGameId());}
    public void deleteAsset(long id){Asset a=getAsset(id);getWritableDatabase().delete("assets","id=?",new String[]{String.valueOf(id)});if(a!=null)touchGame(a.getGameId());}
    public String findSimilarAssetName(long gameId,long excludedId,String name){if(TextUtils.isEmpty(name))return null;try(Cursor c=getReadableDatabase().rawQuery("SELECT name FROM assets WHERE game_id=? AND id<>? AND LOWER(name)=? LIMIT 1",new String[]{String.valueOf(gameId),String.valueOf(excludedId),name.trim().toLowerCase()})){return c.moveToFirst()?c.getString(0):null;}}
    public int[] getGlobalStats(){return new int[]{count("games",null,null),count("assets",null,null),count("assets","status=?",new String[]{String.valueOf(Asset.STATUS_INTEGRATED)})};}
    private int count(String table,String selection,String[] args){try(Cursor c=getReadableDatabase().query(table,new String[]{"COUNT(*)"},selection,args,null,null,null)){return c.moveToFirst()?c.getInt(0):0;}}
    private void touchGame(long id){ContentValues v=new ContentValues();v.put("updated_at",System.currentTimeMillis());getWritableDatabase().update("games",v,"id=?",new String[]{String.valueOf(id)});}

    public String exportJson() throws JSONException{JSONObject root=new JSONObject();root.put("format","CHK_ASSET_MANAGER_BACKUP");root.put("version",1);root.put("exported_at",System.currentTimeMillis());root.put("games",tableToJson("games"));root.put("regions",tableToJson("regions"));root.put("assets",tableToJson("assets"));root.put("asset_images",tableToJson("asset_images"));return root.toString(2);}
    private JSONArray tableToJson(String table)throws JSONException{JSONArray out=new JSONArray();try(Cursor c=getReadableDatabase().query(table,null,null,null,null,null,"id ASC")){String[] cols=c.getColumnNames();while(c.moveToNext()){JSONObject row=new JSONObject();for(String col:cols){int i=c.getColumnIndexOrThrow(col);int type=c.getType(i);if(type==Cursor.FIELD_TYPE_INTEGER)row.put(col,c.getLong(i));else if(type==Cursor.FIELD_TYPE_FLOAT)row.put(col,c.getDouble(i));else if(type==Cursor.FIELD_TYPE_NULL)row.put(col,JSONObject.NULL);else row.put(col,c.getString(i));}out.put(row);}}return out;}
    public void importJson(String json)throws JSONException{JSONObject root=new JSONObject(json);if(!"CHK_ASSET_MANAGER_BACKUP".equals(root.optString("format")))throw new JSONException("Format de sauvegarde non reconnu");SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{db.delete("asset_images",null,null);db.delete("assets",null,null);db.delete("regions",null,null);db.delete("games",null,null);insertRows(db,"games",root.getJSONArray("games"));insertRows(db,"regions",root.getJSONArray("regions"));insertRows(db,"assets",root.getJSONArray("assets"));insertRows(db,"asset_images",root.getJSONArray("asset_images"));db.setTransactionSuccessful();}finally{db.endTransaction();}}
    private void insertRows(SQLiteDatabase db,String table,JSONArray rows)throws JSONException{for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);ContentValues v=new ContentValues();JSONArray names=row.names();if(names==null)continue;for(int j=0;j<names.length();j++){String key=names.getString(j);Object value=row.get(key);if(value==JSONObject.NULL)v.putNull(key);else if(value instanceof Number)v.put(key,((Number)value).longValue());else v.put(key,String.valueOf(value));}db.insertOrThrow(table,null,v);}}
    private String safe(String value){return value==null?"":value;}
}
